import sys

def can_reach_end(path1, path2):
    def simulate(path):
        x, y = 0, 0
        positions = set()
        positions.add((x, y))
        for move in path:
            if move == 'N':
                y += 1
            elif move == 'E':
                x += 1
            elif move == 'S':
                y -= 1
            elif move == 'W':
                x -= 1
            positions.add((x, y))
        return positions

    pos1 = simulate(path1)
    pos2 = simulate(path2)

    for i in range(len(path1)):
        move1 = path1[i]
        move2 = path2[i]

        if move1 != move2:
            return False

        next_x1, next_y1 = 0, 0
        next_x2, next_y2 = 0, 0

        if move1 == 'N':
            next_y1 += 1
            next_y2 += 1
        elif move1 == 'E':
            next_x1 += 1
            next_x2 += 1
        elif move1 == 'S':
            next_y1 -= 1
            next_y2 -= 1
        elif move1 == 'W':
            next_x1 -= 1
            next_x2 -= 1

        if (next_x1, next_y1) not in pos2 or (next_x2, next_y2) not in pos1:
            return False

    return True

n = int(sys.stdin.readline().strip())
path1 = sys.stdin.readline().strip()
path2 = sys.stdin.readline().strip()

if can_reach_end(path1, path2):
    print("YES")
else:
    print("NO")
